def distances_to_zero(a):
    n = len(a)
    left_dist = [float('inf')] * n
    right_dist = [float('inf')] * n

    closest_zero_index = None
    for i in range(n):
        if a[i] == 0:
            closest_zero_index = i
        if closest_zero_index is not None:
            left_dist[i] = i - closest_zero_index

    closest_zero_index = None
    for i in range(n-1, -1, -1):
        if a[i] == 0:
            closest_zero_index = i
        if closest_zero_index is not None:
            right_dist[i] = closest_zero_index - i

    result = [min(left_dist[i], right_dist[i]) for i in range(n)]

    return ' '.join(map(str, result))

