def distances_to_zero(n, arr):
    left = [float('inf')] * n
    right = [float('inf')] * n

    last_zero = -1
    for i in range(n):
        if arr[i] == 0:
            last_zero = i
        else:
            if last_zero != -1:
                left[i] = i - last_zero

    last_zero = -1
    for i in range(n-1, -1, -1):
        if arr[i] == 0:
            last_zero = i
        else:
            if last_zero != -1:
                right[i] = last_zero - i

    result = [min(left[i], right[i]) for i in range(n)]
    return result

# Example usage
